#[path="observations.rs"]mod observations;
use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::{BTreeMap,BTreeSet}};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-ready-arithmetic");assert_eq!(read(r.join("preflight/result.json"))["status"],"complete");let mut config=read(r.join("perf-template.json"));let mut prior:BTreeSet<String>=serde_json::from_value(config["prior_proof_sha256"].clone()).unwrap();let before=prior.len();let mut pins:BTreeMap<String,String>=serde_json::from_value(config["pins"].clone()).unwrap();let mut inventory=BTreeMap::new();let mut analyses=Vec::new();
 for c in config["cases"].as_array().unwrap(){for mode in["off","on"]{let name=format!("{}-{mode}",c["name"].as_str().unwrap());let dir=r.join("preflight-proofs").join(&name).join(Path::new(c["image"].as_str().unwrap()).file_stem().unwrap());let proof=dir.join("0.proof");let public=dir.join("0.public");assert_eq!(fs::metadata(&proof).unwrap().len(),164);assert_eq!(hash(&public),c["public_sha256"].as_str().unwrap());assert!(prior.insert(hash(&proof)));for p in[proof,public]{let h=hash(&p);pins.insert(p.to_str().unwrap().into(),h.clone());inventory.insert(p.to_str().unwrap().to_owned(),h);}
 let log=fs::read_to_string(r.join("preflight").join(format!("verify-{name}/stdout.log"))).unwrap();assert!(log.lines().last().unwrap().contains("verified 1 distinct proofs across 1 pinned keys"));let output=fs::read_to_string(r.join("preflight").join(format!("{name}/stdout.log"))).unwrap();let summary:Value=serde_json::from_str(output.lines().find_map(|s|s.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(summary["workers"],c["workers"]);assert_eq!(summary["rounds"],1);assert_eq!(summary["recorder_storage_bytes"],1572864);
 if mode=="on"{let path=dir.join("readiness.json");let capture=read(&path);assert_eq!(capture.as_array().unwrap().len(),1);let a=observations::inspect(&capture[0],c["workers"].as_u64().unwrap()as usize);analyses.push(json!({"case":c["name"],"analysis":a}));pins.insert(path.to_str().unwrap().into(),hash(path));}else{assert!(!dir.join("readiness.json").exists());}
 }}
 for p in ["observations.rs","qualify-preflight.rs","analyze.rs","analyze","preflight-plan.json","preflight/result.json","profile-addendum.md"]{let p=r.join(p);pins.insert(p.to_str().unwrap().into(),hash(&p));}
 let tool="/home/ubuntu/src/zk-tools/zopro/xtask/target/release/xtask";pins.insert(tool.into(),hash(tool));
 config["prior_proof_sha256"]=json!(prior);config["pins"]=json!(pins);save(r.join("perf-plan.json"),&config);save(r.join("preflight-proof-inventory.json"),&json!(inventory));save(r.join("preflight-analysis.json"),&json!({"prior_before":before,"prior_after":prior.len(),"sdk_requests":24,"distinct_gnark_exports":6,"trace_cases":analyses,"status":"passed"}));println!("Six preflight exports verified fresh; three bounded traces validated; prior{} ->{}",before,prior.len());}
